"use client";
/**
 * Clio bar week: seven bars scaled to the week's busiest day, grown in one after another once the tile has risen.
 * Today's bar is the accent. Each bar is a button: pick a day to read its count in the numeral above.
 */
import { type KeyboardEvent, type ReactNode, useRef, useState } from "react";
import {
  ClioTile,
  type ClioTileProps,
  clioTileAliveDelay,
  useClioAlive,
  useClioCountUp,
} from "./theme";
import { CLIO_MOTION } from "./tokens";

const CSS = `
.clio-week__body{margin-top:auto;display:flex;align-items:flex-end;gap:16px;padding-top:12px;min-height:0}
.clio-week__readout{flex:none;display:flex;flex-direction:column;gap:7px;min-width:72px}
.clio-week__value{font-size:40px}
.clio-week__chart{position:relative;flex:1;min-width:0;display:flex;flex-direction:column;gap:6px}
.clio-week__max{display:flex;align-items:center;gap:6px}
.clio-week__max::before{content:"";flex:1;border-top:1px dashed var(--clio-hairline-strong);transition:border-color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-week__bars{display:flex;align-items:stretch;justify-content:space-between;gap:4px;height:var(--clio-week-height,88px)}
.clio-week__day{all:unset;position:relative;flex:1;min-width:20px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:7px;cursor:pointer;border-radius:8px;-webkit-tap-highlight-color:transparent}
.clio-week__day:focus-visible{outline:2px solid var(--clio-accent);outline-offset:2px}
.clio-week__slot{position:relative;flex:1;width:10px;display:flex;align-items:flex-end}
.clio-week__bar{display:block;width:100%;height:0;min-height:0;border-radius:5px;background:var(--clio-bar);transition:height var(--clio-alive-ms) var(--clio-alive-ease),background-color var(--clio-mode-ms) var(--clio-mode-ease),transform var(--clio-press-ms) var(--clio-press-ease);transition-delay:var(--clio-bar-delay,0ms),0ms,0ms}
.clio-week__day[data-alive] .clio-week__bar{height:max(var(--clio-bar-h),4px)}
.clio-week__day[data-zero] .clio-week__bar{background:var(--clio-hairline-strong)}
.clio-week__day[data-missing] .clio-week__bar{background:transparent;box-shadow:inset 0 0 0 1px var(--clio-hairline-strong);height:8px!important;border-radius:3px}
.clio-week__day[data-today] .clio-week__bar{background:var(--clio-accent)}
.clio-week__day:hover .clio-week__bar{transform:scaleX(1.25)}
.clio-week__day:active .clio-week__bar{transform:scaleX(1.1) scaleY(.98)}
.clio-week__letter{font-family:var(--clio-mono);font-size:10px;line-height:1;color:var(--clio-ink-tertiary);transition:color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-week__day[aria-pressed="true"] .clio-week__letter{color:var(--clio-ink)}
.clio-week__mark{position:absolute;left:50%;bottom:-6px;width:12px;height:2px;margin-left:-6px;border-radius:1px;background:var(--clio-ink);opacity:0;transform:scaleX(.3);transition:opacity 200ms ease,transform 260ms var(--clio-alive-ease),background-color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-week__day[aria-pressed="true"] .clio-week__mark{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){.clio-week__bar{transition:background-color var(--clio-mode-ms) var(--clio-mode-ease)}}
`;

export interface ClioWeekBar {
  /** The day's count; 0 for a missing day. */
  value: number;
  /** Height as a share of the week's busiest day, 0–1. */
  ratio: number;
  /** No count was given for the day. */
  missing: boolean;
}

/**
 * Scales a week to its busiest day. Missing days (null, undefined, not a number or past the end) count as 0 and are
 * marked; negative counts are 0; a week of zeros stays at 0 instead of dividing by it.
 */
export function clioWeekBars(
  values: readonly (number | null | undefined)[],
  length = 7,
): { max: number; bars: ClioWeekBar[] } {
  const days = Array.from({ length: Math.max(0, Math.floor(length)) }, (_, i) => {
    const raw = values[i];
    const missing = typeof raw !== "number" || !Number.isFinite(raw);
    return { value: missing ? 0 : Math.max(0, raw), missing };
  });
  const max = days.reduce((m, d) => Math.max(m, d.value), 0);
  return { max, bars: days.map((d) => ({ ...d, ratio: max > 0 ? d.value / max : 0 })) };
}

export interface ClioWeekDay {
  /** The day's full name, read out and shown in the readout, e.g. "Tuesday". */
  label: string;
  /** The letter under its bar, e.g. "T". */
  short?: string;
  value?: number | null;
}

const WEEK = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
const SAMPLE = [6, 9, 4, 11, 7, 3, 5];

export interface ClioBarWeekProps extends Omit<ClioTileProps, "children" | "label" | "onSelect"> {
  label?: ReactNode;
  /** Seven days in order; a day without a value shows as missing. */
  days?: ClioWeekDay[];
  /** Index of today, drawn in the accent. */
  today?: number | null;
  /** The picked day (controlled). */
  selected?: number;
  defaultSelected?: number;
  onSelectedChange?: (index: number) => void;
  /** The counted thing, plural and singular. */
  unit?: string;
  unitOne?: string;
  /** The caption under the numeral for the picked day. */
  readout?: (day: ClioWeekDay, value: number, isToday: boolean) => ReactNode;
  /** A dashed line at the top with the week's busiest count. */
  showMax?: boolean;
  maxLabel?: (max: number) => ReactNode;
  /** Grow the bars after the rise. Off, they show at full height at once. */
  animate?: boolean;
}

export function ClioBarWeek({
  label = "Saves by day",
  days = WEEK.map((name, i) => ({ label: name, value: SAMPLE[i] })),
  today = 4,
  selected,
  defaultSelected,
  onSelectedChange,
  unit = "saves",
  unitOne = "save",
  readout,
  showMax = true,
  maxLabel = (max) => `${max} on the busiest day`,
  animate = true,
  riseIndex,
  riseDelay,
  className,
  ...tile
}: ClioBarWeekProps) {
  const { max, bars } = clioWeekBars(
    days.map((d) => d.value),
    days.length,
  );
  const fallback =
    defaultSelected ??
    (today !== null && today !== undefined && today >= 0 && today < days.length
      ? today
      : Math.max(0, days.length - 1));
  const [own, setOwn] = useState(fallback);
  const current = Math.min(Math.max(0, selected ?? own), Math.max(0, days.length - 1));
  const pick = (index: number) => {
    if (selected === undefined) setOwn(index);
    onSelectedChange?.(index);
  };
  const aliveDelay = clioTileAliveDelay(riseIndex, riseDelay);
  const alive = useClioAlive(aliveDelay, animate);
  const value = bars[current]?.value ?? 0;
  const shown = useClioCountUp(value, { delay: aliveDelay, enabled: animate });
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const day = days[current];
  const isToday = current === today;
  const noun = (n: number) => (n === 1 ? unitOne : unit);

  const onKey = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const last = days.length - 1;
    const to =
      event.key === "ArrowRight" || event.key === "ArrowDown"
        ? Math.min(last, index + 1)
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? Math.max(0, index - 1)
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? last
              : null;
    if (to === null) return;
    event.preventDefault();
    pick(to);
    refs.current[to]?.focus();
  };

  return (
    <ClioTile
      {...tile}
      label={label}
      riseIndex={riseIndex}
      riseDelay={riseDelay}
      className={className ? `clio-week ${className}` : "clio-week"}
    >
      <style>{CSS}</style>
      <div className="clio-week__body">
        <div className="clio-week__readout">
          <p className="clio-numeral clio-week__value">
            <span aria-hidden="true">{shown}</span>
          </p>
          <p className="clio-caption" aria-live="polite">
            {day ? (
              readout ? (
                readout(day, value, isToday)
              ) : bars[current]?.missing ? (
                `No count for ${day.label}`
              ) : (
                <>
                  <span className="clio-sr">{value} </span>
                  {isToday ? `${noun(value)} today` : `${noun(value)} on ${day.label}`}
                </>
              )
            ) : null}
          </p>
        </div>
        <div className="clio-week__chart">
          {showMax ? <p className="clio-caption clio-week__max">{maxLabel(max)}</p> : null}
          <div
            className="clio-week__bars"
            role="group"
            aria-label={typeof label === "string" ? label : "Days of the week"}
          >
            {days.map((d, i) => {
              const bar = bars[i] ?? { value: 0, ratio: 0, missing: true };
              return (
                <button
                  key={`${d.label}-${i}`}
                  ref={(node) => {
                    refs.current[i] = node;
                  }}
                  type="button"
                  className="clio-week__day"
                  aria-pressed={i === current}
                  aria-label={
                    bar.missing
                      ? `${d.label}, no count`
                      : `${d.label}, ${bar.value} ${noun(bar.value)}${i === today ? ", today" : ""}`
                  }
                  tabIndex={i === current ? 0 : -1}
                  onClick={() => pick(i)}
                  onKeyDown={(event) => onKey(event, i)}
                  data-alive={alive ? "" : undefined}
                  data-today={i === today ? "" : undefined}
                  data-zero={!bar.missing && bar.value === 0 ? "" : undefined}
                  data-missing={bar.missing ? "" : undefined}
                  style={{
                    ["--clio-bar-h" as string]: `${(bar.ratio * 100).toFixed(2)}%`,
                    ["--clio-bar-delay" as string]: `${i * CLIO_MOTION.alive.stagger}ms`,
                  }}
                >
                  <span className="clio-week__slot" aria-hidden="true">
                    <span className="clio-week__bar" />
                  </span>
                  <span className="clio-week__letter" aria-hidden="true">
                    {d.short ?? d.label.slice(0, 1)}
                  </span>
                  <span className="clio-week__mark" aria-hidden="true" />
                </button>
              );
            })}
          </div>
        </div>
      </div>
    </ClioTile>
  );
}
